# Advanced optional Bayesian workflows for gp3bayes
#
# This file is generated by gp3bayes_advanced_extension_installer.R.
# The functions remain optional, conservative adapters around established
# Bayesian packages. They do not provide automatic model selection, automatic
# adequacy claims, causal interpretation, or unrestricted formulas/families.

.gp3x_stop <- function(...) {
  stop(paste0(...), call. = FALSE)
}

.gp3x_require <- function(package, purpose) {
  if (!requireNamespace(package, quietly = TRUE)) {
    .gp3x_stop(
      "Optional package `", package, "` is required to ", purpose, "."
    )
  }
  invisible(TRUE)
}

.gp3x_scalar_integer <- function(x, name, minimum = 0L) {
  if (!is.numeric(x) || length(x) != 1L || is.na(x) ||
      !is.finite(x) || x != floor(x) || x < minimum) {
    .gp3x_stop("`", name, "` must be one integer >= ", minimum, ".")
  }
  as.integer(x)
}

.gp3x_scalar_number <- function(
  x,
  name,
  lower = -Inf,
  upper = Inf,
  lower_open = FALSE,
  upper_open = FALSE
) {
  if (!is.numeric(x) || length(x) != 1L || is.na(x) || !is.finite(x)) {
    .gp3x_stop("`", name, "` must be one finite numeric value.")
  }
  lower_ok <- if (lower_open) x > lower else x >= lower
  upper_ok <- if (upper_open) x < upper else x <= upper
  if (!lower_ok || !upper_ok) {
    .gp3x_stop("`", name, "` is outside the permitted interval.")
  }
  as.numeric(x)
}

.gp3x_unwrap_fit <- function(x) {
  if (inherits(x, "gp3bayes_fit")) {
    return(x$backend_fit)
  }
  if (inherits(x, "brmsfit")) {
    return(x)
  }
  .gp3x_stop(
    "`x` must be a gp3bayes fit or a `brmsfit` object."
  )
}

.gp3x_call_supported <- function(fun, args) {
  formal_names <- names(formals(fun))
  if (!"..." %in% formal_names) {
    args <- args[names(args) %in% formal_names]
  }
  do.call(fun, args)
}

.gp3x_backend_version <- function(package) {
  if (!requireNamespace(package, quietly = TRUE)) {
    return(NA_character_)
  }
  as.character(utils::packageVersion(package))
}

.gp3x_interaction_coef <- function(translation) {
  prior_table <- brms::get_prior(
    formula = translation$formula,
    data = translation$specification$prepared$data,
    family = translation$family_object
  )
  prior_table <- as.data.frame(prior_table, stringsAsFactors = FALSE)

  candidates <- prior_table$coef[
    prior_table$class == "b" &
      !is.na(prior_table$coef) &
      nzchar(prior_table$coef) &
      grepl(":", prior_table$coef, fixed = TRUE)
  ]
  candidates <- unique(candidates)

  if (length(candidates) != 1L) {
    .gp3x_stop(
      "The approved specification must contain exactly one identifiable ",
      "two-way interaction coefficient; found ", length(candidates), "."
    )
  }
  candidates[[1L]]
}

.gp3x_apply_interaction_prior <- function(
  translation,
  scale,
  tag = "interaction"
) {
  .gp3x_require("brms", "translate a coefficient-specific interaction prior")
  scale <- .gp3x_scalar_number(
    scale, "interaction_scale", lower = 0, lower_open = TRUE
  )

  coef_name <- .gp3x_interaction_coef(translation)
  prior_text <- paste0("normal(0, ", format(scale, trim = TRUE), ")")

  interaction_prior <- brms::set_prior(
    prior = prior_text,
    class = "b",
    coef = coef_name,
    tag = tag
  )

  translated_priors <- c(translation$priors, interaction_prior)
  validated <- brms::validate_prior(
    prior = translated_priors,
    formula = translation$formula,
    data = translation$specification$prepared$data,
    family = translation$family_object
  )

  table <- as.data.frame(validated, stringsAsFactors = FALSE)
  matched <- table$class == "b" &
    table$coef == coef_name &
    table$source == "user"

  if (!any(matched)) {
    .gp3x_stop(
      "The coefficient-specific interaction prior was not retained by brms."
    )
  }

  translation$priors <- translated_priors
  translation$validated_priors <- validated
  translation$parameter_table <- table
  translation$prior_text <- c(
    translation$prior_text,
    interaction = prior_text
  )
  translation$interaction_prior <- list(
    coefficient = coef_name,
    scale = scale,
    prior = prior_text,
    tag = tag
  )
  translation$translation_version <- "0.2"
  translation
}

#' Report Optional Bayesian Backend Capabilities
#'
#' Audits package availability and, where possible, runtime usability for the
#' optional Bayesian extensions.
#'
#' @return A `gp3bayes_backend_capabilities` data frame.
#' @export
bayesian_backend_capabilities <- function() {
  packages <- c(
    "brms", "rstan", "cmdstanr", "loo",
    "priorsense", "detectseparation", "SBC"
  )

  installed <- vapply(
    packages,
    requireNamespace,
    quietly = TRUE,
    FUN.VALUE = logical(1L)
  )

  versions <- vapply(
    packages,
    .gp3x_backend_version,
    FUN.VALUE = character(1L)
  )

  usable <- installed
  detail <- ifelse(installed, "package available", "package not installed")

  cmd_index <- match("cmdstanr", packages)
  if (installed[[cmd_index]]) {
    cmd_check <- tryCatch(
      {
        cmdstanr::check_cmdstan_toolchain(quiet = TRUE)
        path <- cmdstanr::cmdstan_path()
        version <- as.character(cmdstanr::cmdstan_version())
        list(
          usable = nzchar(path),
          detail = paste0("CmdStan ", version, " at ", path)
        )
      },
      error = function(e) {
        list(usable = FALSE, detail = conditionMessage(e))
      }
    )
    usable[[cmd_index]] <- cmd_check$usable
    detail[[cmd_index]] <- cmd_check$detail
  }

  result <- data.frame(
    component = packages,
    installed = unname(installed),
    version = unname(versions),
    usable = unname(usable),
    detail = unname(detail),
    stringsAsFactors = FALSE
  )

  structure(
    result,
    class = c("gp3bayes_backend_capabilities", "data.frame")
  )
}

#' @export
print.gp3bayes_backend_capabilities <- function(x, ...) {
  cat("\nOptional Bayesian capabilities\n\n")
  print.data.frame(x, row.names = FALSE)
  invisible(x)
}

#' Check the CmdStanR Backend
#'
#' Checks package availability, the C++ toolchain, and a configured CmdStan
#' installation. No installation or repair is performed automatically.
#'
#' @param strict Whether to stop instead of returning a failed audit.
#'
#' @return A list with status, version, path, and diagnostic detail.
#' @export
check_cmdstan_backend <- function(strict = FALSE) {
  if (!is.logical(strict) || length(strict) != 1L || is.na(strict)) {
    .gp3x_stop("`strict` must be TRUE or FALSE.")
  }

  result <- tryCatch(
    {
      .gp3x_require("cmdstanr", "check the CmdStan backend")
      cmdstanr::check_cmdstan_toolchain(quiet = TRUE)
      path <- cmdstanr::cmdstan_path()
      version <- as.character(cmdstanr::cmdstan_version())
      list(
        status = "pass",
        usable = TRUE,
        path = path,
        version = version,
        detail = "CmdStanR, the toolchain, and CmdStan are available."
      )
    },
    error = function(e) {
      list(
        status = "fail",
        usable = FALSE,
        path = NA_character_,
        version = NA_character_,
        detail = conditionMessage(e)
      )
    }
  )

  class(result) <- "gp3bayes_cmdstan_backend_audit"

  if (strict && !isTRUE(result$usable)) {
    .gp3x_stop("CmdStan backend audit failed: ", result$detail)
  }
  result
}

#' @export
print.gp3bayes_cmdstan_backend_audit <- function(x, ...) {
  cat("\nCmdStan backend audit\n")
  cat(" Status: ", x$status, "\n", sep = "")
  cat(" Usable: ", x$usable, "\n", sep = "")
  if (!is.na(x$version)) {
    cat(" Version: ", x$version, "\n", sep = "")
  }
  if (!is.na(x$path)) {
    cat(" Path: ", x$path, "\n", sep = "")
  }
  cat(" Detail: ", x$detail, "\n", sep = "")
  invisible(x)
}

#' Specify a Binary Model with a Separate Interaction Prior
#'
#' Retains the approved binary model contract while recording a common
#' main-effect prior scale and a narrower coefficient-specific interaction
#' prior scale.
#'
#' @param prepared A `gp3bayes_binary_prepared` object containing one approved
#'   two-way interaction.
#' @param baseline Plausible baseline event probability.
#' @param intercept_scale Intercept-prior scale.
#' @param main_effect_scale Common population main-effect prior scale.
#' @param interaction_scale Interaction prior scale.
#' @param group_sd_scale Group-level standard-deviation prior scale.
#' @param correlation_eta LKJ shape.
#' @param student_df Student-t degrees of freedom.
#'
#' @return A binary model specification with advanced prior metadata.
#' @export
specify_binary_model_with_interaction_prior <- function(
  prepared,
  baseline,
  intercept_scale = 1.5,
  main_effect_scale = 0.75,
  interaction_scale = 0.50,
  group_sd_scale = 1,
  correlation_eta = 2,
  student_df = 3
) {
  if (!inherits(prepared, "gp3bayes_binary_prepared")) {
    .gp3x_stop("`prepared` must be a binary prepared object.")
  }
  if (is.null(prepared$contract$interaction)) {
    .gp3x_stop(
      "A declared two-way interaction is required for this specification."
    )
  }

  specification <- specify_binary_model(
    prepared = prepared,
    baseline = baseline,
    intercept_scale = intercept_scale,
    coefficient_scale = main_effect_scale,
    group_sd_scale = group_sd_scale,
    correlation_eta = correlation_eta,
    student_df = student_df
  )

  specification$advanced_priors <- list(
    main_effect_scale = .gp3x_scalar_number(
      main_effect_scale, "main_effect_scale", 0, lower_open = TRUE
    ),
    interaction_scale = .gp3x_scalar_number(
      interaction_scale, "interaction_scale", 0, lower_open = TRUE
    ),
    interaction = prepared$contract$interaction,
    interaction_tag = "interaction"
  )
  specification$advanced_prior_version <- "0.2"

  class(specification) <- c(
    "gp3bayes_binary_interaction_prior_specification",
    class(specification)
  )
  specification
}

#' Specify a Duration Model with a Separate Interaction Prior
#'
#' Uses the candidate duration defaults of 0.35 for population main effects
#' and 0.25 for the approved two-way interaction.
#'
#' @inheritParams specify_binary_model_with_interaction_prior
#' @param baseline Plausible baseline median in the recorded outcome unit.
#' @param main_effect_scale Common population main-effect prior scale.
#' @param interaction_scale Interaction prior scale.
#' @param residual_scale Lognormal residual-scale prior scale.
#'
#' @return A duration model specification with advanced prior metadata.
#' @export
specify_duration_model_with_interaction_prior <- function(
  prepared,
  baseline,
  intercept_scale = 1,
  main_effect_scale = 0.35,
  interaction_scale = 0.25,
  group_sd_scale = 0.5,
  residual_scale = 0.5,
  correlation_eta = 2,
  student_df = 3
) {
  if (!inherits(prepared, "gp3bayes_duration_prepared")) {
    .gp3x_stop("`prepared` must be a duration prepared object.")
  }
  if (is.null(prepared$contract$interaction)) {
    .gp3x_stop(
      "A declared two-way interaction is required for this specification."
    )
  }

  specification <- specify_duration_model(
    prepared = prepared,
    baseline = baseline,
    intercept_scale = intercept_scale,
    coefficient_scale = main_effect_scale,
    group_sd_scale = group_sd_scale,
    residual_scale = residual_scale,
    correlation_eta = correlation_eta,
    student_df = student_df
  )

  specification$advanced_priors <- list(
    main_effect_scale = .gp3x_scalar_number(
      main_effect_scale, "main_effect_scale", 0, lower_open = TRUE
    ),
    interaction_scale = .gp3x_scalar_number(
      interaction_scale, "interaction_scale", 0, lower_open = TRUE
    ),
    interaction = prepared$contract$interaction,
    interaction_tag = "interaction"
  )
  specification$advanced_prior_version <- "0.2"

  class(specification) <- c(
    "gp3bayes_duration_interaction_prior_specification",
    class(specification)
  )
  specification
}

#' Summarise Separate Interaction Prior Metadata
#'
#' @param specification An advanced binary or duration specification.
#'
#' @return A one-row data frame.
#' @export
interaction_prior_summary <- function(specification) {
  metadata <- specification$advanced_priors
  if (is.null(metadata)) {
    .gp3x_stop(
      "`specification` does not contain separate interaction-prior metadata."
    )
  }

  data.frame(
    family = specification$family,
    interaction = paste(metadata$interaction, collapse = ":"),
    main_effect_scale = metadata$main_effect_scale,
    interaction_scale = metadata$interaction_scale,
    interaction_tag = metadata$interaction_tag,
    stringsAsFactors = FALSE
  )
}

#' Translate an Advanced Binary Specification to brms
#'
#' @param specification An advanced binary specification.
#'
#' @return A validated restricted brms translation.
#' @export
translate_binary_model_with_interaction_prior <- function(specification) {
  if (!inherits(
    specification,
    "gp3bayes_binary_interaction_prior_specification"
  )) {
    .gp3x_stop(
      "`specification` must be created by ",
      "`specify_binary_model_with_interaction_prior()`."
    )
  }

  translation <- translate_binary_model_to_brms(specification)
  translation <- .gp3x_apply_interaction_prior(
    translation,
    specification$advanced_priors$interaction_scale,
    tag = specification$advanced_priors$interaction_tag
  )
  class(translation) <- c(
    "gp3bayes_binary_advanced_backend_specification",
    class(translation)
  )
  translation
}

#' Translate an Advanced Duration Specification to brms
#'
#' @param specification An advanced duration specification.
#'
#' @return A validated restricted brms translation.
#' @export
translate_duration_model_with_interaction_prior <- function(specification) {
  if (!inherits(
    specification,
    "gp3bayes_duration_interaction_prior_specification"
  )) {
    .gp3x_stop(
      "`specification` must be created by ",
      "`specify_duration_model_with_interaction_prior()`."
    )
  }

  translation <- translate_duration_model_to_brms(specification)
  translation <- .gp3x_apply_interaction_prior(
    translation,
    specification$advanced_priors$interaction_scale,
    tag = specification$advanced_priors$interaction_tag
  )
  class(translation) <- c(
    "gp3bayes_duration_advanced_backend_specification",
    class(translation)
  )
  translation
}

.gp3x_translate_for_backend <- function(specification) {
  if (inherits(
    specification,
    "gp3bayes_binary_interaction_prior_specification"
  )) {
    return(translate_binary_model_with_interaction_prior(specification))
  }
  if (inherits(
    specification,
    "gp3bayes_duration_interaction_prior_specification"
  )) {
    return(translate_duration_model_with_interaction_prior(specification))
  }
  if (inherits(specification, "gp3bayes_binary_model_specification")) {
    return(translate_binary_model_to_brms(specification))
  }
  if (inherits(specification, "gp3bayes_duration_model_specification")) {
    return(translate_duration_model_to_brms(specification))
  }
  .gp3x_stop("Unsupported specification class.")
}

.gp3x_fit_backend <- function(
  specification,
  backend,
  chains,
  iter,
  warmup,
  cores,
  seed,
  adapt_delta,
  max_treedepth,
  refresh
) {
  backend <- match.arg(backend, c("rstan", "cmdstanr"))
  chains <- .gp3x_scalar_integer(chains, "chains", 1L)
  iter <- .gp3x_scalar_integer(iter, "iter", 100L)
  warmup <- .gp3x_scalar_integer(warmup, "warmup", 0L)
  cores <- .gp3x_scalar_integer(cores, "cores", 1L)
  seed <- .gp3x_scalar_integer(seed, "seed", 0L)
  max_treedepth <- .gp3x_scalar_integer(
    max_treedepth, "max_treedepth", 5L
  )
  refresh <- .gp3x_scalar_integer(refresh, "refresh", 0L)
  adapt_delta <- .gp3x_scalar_number(
    adapt_delta,
    "adapt_delta",
    lower = 0,
    upper = 1,
    lower_open = TRUE,
    upper_open = TRUE
  )

  if (warmup >= iter) {
    .gp3x_stop("`warmup` must be smaller than `iter`.")
  }
  if (cores > chains) {
    .gp3x_stop("`cores` cannot exceed `chains`.")
  }

  .gp3x_require("brms", "fit an advanced gp3bayes model")
  if (identical(backend, "rstan")) {
    .gp3x_require("rstan", "use the rstan sampling backend")
  } else {
    check_cmdstan_backend(strict = TRUE)
  }

  translation <- .gp3x_translate_for_backend(specification)

  backend_fit <- brms::brm(
    formula = translation$formula,
    data = specification$prepared$data,
    family = translation$family_object,
    prior = translation$priors,
    backend = backend,
    algorithm = "sampling",
    sample_prior = "no",
    save_pars = brms::save_pars(all = TRUE),
    chains = chains,
    iter = iter,
    warmup = warmup,
    cores = cores,
    seed = seed,
    control = list(
      adapt_delta = adapt_delta,
      max_treedepth = max_treedepth
    ),
    refresh = refresh
  )

  family <- specification$family
  family_class <- if (identical(family, "binary")) {
    "gp3bayes_binary_fit"
  } else {
    "gp3bayes_duration_fit"
  }

  versions <- c(
    brms = .gp3x_backend_version("brms"),
    backend = .gp3x_backend_version(backend)
  )
  names(versions)[[2L]] <- backend

  result <- list(
    fit_version = "0.2",
    family = family,
    model_family = specification$model_family,
    specification = specification,
    translation = translation,
    backend_fit = backend_fit,
    outcome_unit = specification$outcome_unit %||% NULL,
    backend_interface = "brms",
    sampling_backend = backend,
    algorithm = "sampling",
    sampling = list(
      chains = chains,
      iter = iter,
      warmup = warmup,
      post_warmup_iterations = iter - warmup,
      cores = cores,
      seed = seed,
      adapt_delta = adapt_delta,
      max_treedepth = max_treedepth,
      refresh = refresh
    ),
    package_versions = versions,
    unrestricted_formula = FALSE,
    fit_performed = TRUE,
    diagnostics_assessed = FALSE,
    posterior_adequacy_established = FALSE
  )

  structure(
    result,
    class = c(
      "gp3bayes_backend_portable_fit",
      family_class,
      "gp3bayes_fit"
    )
  )
}

`%||%` <- function(x, y) {
  if (is.null(x)) y else x
}

#' Fit a Binary Model with a Selected Full-MCMC Backend
#'
#' The formula and family remain contract-restricted. The only selectable
#' implementation detail is whether brms delegates full MCMC sampling to
#' rstan or CmdStanR.
#'
#' @param specification An approved binary model specification.
#' @param backend Either `"rstan"` or `"cmdstanr"`.
#' @param chains Number of chains.
#' @param iter Total iterations per chain.
#' @param warmup Warmup iterations per chain.
#' @param cores Number of cores, not exceeding chains.
#' @param seed Non-negative integer seed.
#' @param adapt_delta NUTS target acceptance probability.
#' @param max_treedepth NUTS maximum tree depth.
#' @param refresh Progress refresh interval.
#'
#' @return A `gp3bayes_backend_portable_fit`.
#' @export
fit_binary_model_backend <- function(
  specification,
  backend = c("rstan", "cmdstanr"),
  chains = 4L,
  iter = 2000L,
  warmup = 1000L,
  cores = .gp3b_default_cores(chains),
  seed = 1L,
  adapt_delta = 0.95,
  max_treedepth = 12L,
  refresh = 0L
) {
  if (!inherits(specification, "gp3bayes_binary_model_specification")) {
    .gp3x_stop("`specification` must be an approved binary specification.")
  }
  .gp3x_fit_backend(
    specification = specification,
    backend = match.arg(backend),
    chains = chains,
    iter = iter,
    warmup = warmup,
    cores = cores,
    seed = seed,
    adapt_delta = adapt_delta,
    max_treedepth = max_treedepth,
    refresh = refresh
  )
}

