#' @export
print.gp3bayes_backend_portable_fit <- function(x, ...) {
  cat("\nBackend-portable gp3bayes fit\n")
  cat(" Family: ", x$family, "\n", sep = "")
  cat(" Formula: ", x$translation$formula_text, "\n", sep = "")
  cat(" Interface: brms\n")
  cat(" Sampling backend: ", x$sampling_backend, "\n", sep = "")
  cat(" Algorithm: full MCMC sampling\n")
  cat(" Chains: ", x$sampling$chains, "\n", sep = "")
  cat(" Iterations per chain: ", x$sampling$iter, "\n", sep = "")
  cat(" Diagnostics assessed: FALSE\n")
  cat(" Posterior adequacy established: FALSE\n")
  invisible(x)
}

#' Detect Separation in the Binary Fixed-Effects Screen
#'
#' Runs `detectseparation::detect_separation()` as a pre-fit fixed-effects
#' screen. This screen does not replace the hierarchical model or prove that
#' the Bayesian posterior is adequate.
#'
#' @param x An approved binary specification, or a data frame when `formula`
#'   is supplied.
#' @param formula Optional fixed-effects binomial formula.
#' @param data Optional data frame. It overrides data extracted from `x`.
#'
#' @return A `gp3bayes_separation_screen`.
#' @export
detect_binary_separation <- function(x, formula = NULL, data = NULL) {
  .gp3x_require(
    "detectseparation",
    "screen a binary fixed-effects design for separation"
  )

  specification_input <- inherits(
    x,
    "gp3bayes_binary_model_specification"
  )

  if (specification_input) {
    if (is.null(data)) {
      data <- x$prepared$data
    }

    if (is.null(formula)) {
      formula <- x$fixed_formula
    }

    if (is.null(formula) && !is.null(x$prepared$fixed_formula)) {
      formula <- x$prepared$fixed_formula
    }

  } else if (is.data.frame(x)) {
    if (is.null(data)) {
      data <- x
    }

  } else {
    .gp3x_stop(
      "`x` must be an approved binary specification or a data frame."
    )
  }

  if (!inherits(formula, "formula")) {
    .gp3x_stop(
      "`formula` must be supplied as a formula."
    )
  }

  if (!is.data.frame(data)) {
    .gp3x_stop(
      "`data` must be a data frame."
    )
  }

  response_name <- all.vars(formula[[2L]])

  if (
    length(response_name) != 1L ||
    !response_name %in% names(data)
  ) {
    .gp3x_stop(
      "The separation-screen response must identify one column in `data`."
    )
  }

  response <- data[[response_name]]

  valid_binary <- all(
    stats::na.omit(response) %in% c(0, 1, FALSE, TRUE)
  )

  if (!valid_binary) {
    .gp3x_stop(
      "The separation-screen outcome must be binary."
    )
  }

  screen <- stats::glm(
    formula = formula,
    data = data,
    family = stats::binomial(link = "logit"),
    method = detectseparation::detect_separation
  )

  coefficients_raw <- stats::coef(screen)

  coefficient_names <- names(coefficients_raw)

  coefficients <- as.numeric(coefficients_raw)

  names(coefficients) <- coefficient_names

  infinite <- is.infinite(coefficients)
  separated <- any(infinite)

  coefficient_table <- data.frame(
    coefficient = names(coefficients),
    separation_code = unname(coefficients),
    infinite = unname(infinite),
    direction = ifelse(
      coefficients == Inf,
      "positive_infinity",
      ifelse(
        coefficients == -Inf,
        "negative_infinity",
        "finite"
      )
    ),
    stringsAsFactors = FALSE
  )

  structure(
    list(
      status = if (separated) "review" else "pass",
      separation_detected = separated,
      coefficients = coefficient_table,
      formula = formula,
      n_observations = nrow(data),
      raw = screen,
      screening_only = TRUE,
      interpretation = paste(
        "This is a fixed-effects logistic separation screen.",
        "Grouping terms from the hierarchical specification are not",
        "included in this screening GLM.",
        "The screen neither fits nor validates the hierarchical",
        "Bayesian model."
      )
    ),
    class = "gp3bayes_separation_screen"
  )
}
#' @export
print.gp3bayes_separation_screen <- function(x, ...) {
  cat("\nBinary separation screen\n")
  cat(" Status: ", x$status, "\n", sep = "")
  cat(" Separation detected: ", x$separation_detected, "\n", sep = "")
  cat(" Observations: ", x$n_observations, "\n", sep = "")
  print(x$coefficients, row.names = FALSE)
  cat("\n", x$interpretation, "\n", sep = "")
  invisible(x)
}

#' @method plot gp3bayes_separation_screen
#' @export
plot.gp3bayes_separation_screen <- function(
    x,
    main = "Fixed-effects separation screen",
    ...
) {
  if (!inherits(x, "gp3bayes_separation_screen")) {
    .gp3x_stop(
      "`x` must be a `gp3bayes_separation_screen` object."
    )
  }

  codes <- as.numeric(
    unlist(
      x$coefficients[["separation_code"]],
      use.names = FALSE
    )
  )

  coefficient_names <- as.character(
    x$coefficients[["coefficient"]]
  )

  if (
    length(codes) == 0L ||
    length(codes) != length(coefficient_names) ||
    anyNA(codes)
  ) {
    .gp3x_stop(
      "The separation coefficient table cannot be plotted."
    )
  }

  display_codes <- ifelse(
    is.infinite(codes),
    sign(codes),
    0
  )

  graphics::barplot(
    height = display_codes,
    names.arg = coefficient_names,
    las = 2,
    ylim = c(-1.2, 1.2),
    ylab = "-1: -Inf, 0: finite, 1: +Inf",
    main = main,
    ...
  )

  graphics::abline(
    h = 0,
    lty = 2
  )

  invisible(x)
}


.gp3x_wrap_loo <- function(raw, source = NULL) {
  .gp3x_require("loo", "summarise PSIS-LOO diagnostics")

  if (!inherits(raw, "loo")) {
    .gp3x_stop(
      "`raw` must be a `loo` object."
    )
  }

  pareto_k <- loo::pareto_k_values(raw)

  if (!is.numeric(pareto_k)) {
    pareto_k <- as.numeric(pareto_k)
  }

  flagged <- loo::pareto_k_ids(raw)

  if (is.null(flagged)) {
    flagged <- integer()
  }

  flagged <- as.integer(flagged)

  severe <- which(
    is.finite(pareto_k) & pareto_k >= 1
  )

  status <- if (length(severe) > 0L) {
    "fail"
  } else if (length(flagged) > 0L) {
    "review"
  } else {
    "pass"
  }

  pareto_table <- tryCatch(
    loo::pareto_k_table(raw),
    error = function(e) NULL
  )

  mcse <- tryCatch(
    loo::mcse_loo(raw),
    error = function(e) NA_real_
  )

  structure(
    list(
      status = status,
      raw = raw,
      pareto_k = pareto_k,
      flagged_observations = flagged,
      severe_observations = as.integer(severe),
      pareto_k_table = pareto_table,
      mcse_loo = mcse,
      source = source,
      automatic_selection = FALSE,
      interpretation = paste(
        "PSIS-LOO estimates out-of-sample predictive performance.",
        "Pareto-k diagnostics must be inspected before interpretation.",
        "No model is selected automatically."
      )
    ),
    class = "gp3bayes_psis_loo"
  )
}

#' Compute PSIS-LOO for a gp3bayes Fit
#'
#' @param fit A gp3bayes fit or `brmsfit`.
#' @param moment_match Whether to request moment matching.
#' @param reloo Whether to request exact refits for problematic observations.
#' @param cores Number of cores.
#' @param save_psis Whether to retain the PSIS object.
#'
#' @return A conservative `gp3bayes_psis_loo` result.
#' @export
compute_psis_loo <- function(
  fit,
  moment_match = FALSE,
  reloo = FALSE,
  cores = 1L,
  save_psis = TRUE
) {
  .gp3x_require("loo", "compute PSIS-LOO")
  .gp3x_require("brms", "compute PSIS-LOO for a brms fit")
  backend_fit <- .gp3x_unwrap_fit(fit)

  raw <- loo::loo(
    backend_fit,
    moment_match = moment_match,
    reloo = reloo,
    cores = cores,
    save_psis = save_psis
  )
  .gp3x_wrap_loo(raw, source = fit)
}

#' Compute PSIS-LOO from a Log-Likelihood Matrix
#'
#' This function supports deterministic tests and advanced workflows that
#' already possess pointwise log-likelihood draws.
#'
#' @param log_lik Matrix with posterior draws in rows and observations in
#'   columns.
#' @param chain_id Optional chain identifier for each row.
#' @inheritParams compute_psis_loo
#'
#' @return A `gp3bayes_psis_loo`.
#' @export
compute_psis_loo_from_log_lik <- function(
  log_lik,
  chain_id = NULL,
  cores = 1L,
  save_psis = TRUE
) {
  .gp3x_require("loo", "compute PSIS-LOO")
  if (!is.matrix(log_lik) || !is.numeric(log_lik) ||
      anyNA(log_lik) || any(!is.finite(log_lik))) {
    .gp3x_stop("`log_lik` must be a finite numeric matrix.")
  }

  r_eff <- NULL
  if (!is.null(chain_id)) {
    if (length(chain_id) != nrow(log_lik)) {
      .gp3x_stop("`chain_id` must have one value per log-likelihood row.")
    }
    r_eff <- loo::relative_eff(exp(log_lik), chain_id = chain_id)
  }

  raw <- loo::loo(
    log_lik,
    r_eff = r_eff,
    cores = cores,
    save_psis = save_psis
  )
  .gp3x_wrap_loo(raw, source = "log_likelihood_matrix")
}

#' Identify Influential PSIS-LOO Observations
#'
#' @param x A `gp3bayes_psis_loo` or raw loo object.
#' @param threshold Optional explicit Pareto-k threshold.
#' @param data Optional observation-level data to append.
#'
#' @return A data frame of flagged observations.
#' @export
identify_loo_influential_observations <- function(
  x,
  threshold = NULL,
  data = NULL
) {
  .gp3x_require("loo", "inspect Pareto-k diagnostics")
  raw <- if (inherits(x, "gp3bayes_psis_loo")) x$raw else x
  k <- loo::pareto_k_values(raw)
  influence <- loo::pareto_k_influence_values(raw)

  ids <- if (is.null(threshold)) {
    loo::pareto_k_ids(raw)
  } else {
    threshold <- .gp3x_scalar_number(threshold, "threshold")
    which(k >= threshold)
  }

  result <- data.frame(
    observation = as.integer(ids),
    pareto_k = k[ids],
    influence_pareto_k = influence[ids],
    severe = k[ids] >= 1,
    stringsAsFactors = FALSE
  )

  if (!is.null(data)) {
    if (!is.data.frame(data) || nrow(data) != length(k)) {
      .gp3x_stop(
        "`data` must have one row per PSIS-LOO observation."
      )
    }
    result <- cbind(result, data[ids, , drop = FALSE])
  }
  result
}

#' Compare Models with PSIS-LOO
#'
#' @param models Named list of gp3bayes fits, `brmsfit` objects, or
#'   `gp3bayes_psis_loo` objects.
#' @inheritParams compute_psis_loo
#'
#' @return A `gp3bayes_loo_comparison`. The result never selects a model.
#' @export
compare_psis_loo <- function(
  models,
  moment_match = FALSE,
  reloo = FALSE,
  cores = 1L
) {
  .gp3x_require("loo", "compare PSIS-LOO results")
  if (!is.list(models) || length(models) < 2L) {
    .gp3x_stop("`models` must be a list containing at least two models.")
  }
  if (is.null(names(models)) || any(!nzchar(names(models))) ||
      anyDuplicated(names(models))) {
    .gp3x_stop("`models` must have unique non-empty names.")
  }

  wrapped <- lapply(
    models,
    function(model) {
      if (inherits(model, "gp3bayes_psis_loo")) {
        model
      } else {
        compute_psis_loo(
          model,
          moment_match = moment_match,
          reloo = reloo,
          cores = cores
        )
      }
    }
  )

  observation_counts <- vapply(
    wrapped,
    function(x) nrow(x$raw$pointwise),
    integer(1L)
  )
  if (length(unique(observation_counts)) != 1L) {
    .gp3x_stop(
      "All models must contain the same number of pointwise observations."
    )
  }

  raw_list <- lapply(wrapped, `[[`, "raw")
  comparison <- loo::loo_compare(raw_list)
  any_problem <- any(vapply(
    wrapped,
    function(x) x$status != "pass",
    logical(1L)
  ))

  structure(
    list(
      status = if (any_problem) "review" else "review",
      comparison = comparison,
      loo = wrapped,
      automatic_selection = FALSE,
      interpretation = paste(
        "ELPD differences and uncertainty are descriptive.",
        "No model is automatically selected."
      )
    ),
    class = "gp3bayes_loo_comparison"
  )
}

#' Compute LOO Model-Averaging Weights
#'
#' @param x A `gp3bayes_loo_comparison` or named list of PSIS-LOO objects.
#' @param method Either stacking or pseudo-BMA.
#' @param cores Number of cores.
#'
#' @return A `gp3bayes_loo_weights` object.
#' @export
compute_loo_model_weights <- function(
  x,
  method = c("stacking", "pseudobma"),
  cores = 1L
) {
  .gp3x_require("loo", "compute LOO model weights")
  method <- match.arg(method)

  loo_list <- if (inherits(x, "gp3bayes_loo_comparison")) {
    lapply(x$loo, `[[`, "raw")
  } else if (is.list(x)) {
    lapply(
      x,
      function(item) {
        if (inherits(item, "gp3bayes_psis_loo")) item$raw else item
      }
    )
  } else {
    .gp3x_stop(
      "`x` must be a LOO comparison or a list of LOO objects."
    )
  }

  weights <- loo::loo_model_weights(
    loo_list,
    method = method,
    cores = cores
  )

  structure(
    list(
      method = method,
      weights = weights,
      automatic_selection = FALSE,
      interpretation = paste(
        "Weights combine predictive distributions.",
        "They are not evidence that a single model is substantively correct."
      )
    ),
    class = "gp3bayes_loo_weights"
  )
}

#' @export
print.gp3bayes_psis_loo <- function(x, ...) {
  cat("\nPSIS-LOO audit\n")
  cat(" Status: ", x$status, "\n", sep = "")
  print(x$raw)
