#' Assess Power-Scaled Prior and Likelihood Sensitivity
#'
#' Delegates to priorsense while retaining a conservative review status.
#' Low local sensitivity does not prove that prior choices are irrelevant or
#' that a model is robust.
#'
#' @param fit A gp3bayes fit or `brmsfit`.
#' @param variable Optional posterior variables to inspect.
#' @param prior_selection Optional tagged priors to perturb.
#' @param likelihood_selection Optional likelihood subset.
#'
#' @return A `gp3bayes_powerscale_sensitivity`.
#' @export
assess_powerscaled_sensitivity <- function(
  fit,
  variable = NULL,
  prior_selection = NULL,
  likelihood_selection = NULL
) {
  .gp3x_require("priorsense", "assess power-scaled sensitivity")
  backend_fit <- .gp3x_unwrap_fit(fit)

  args <- list(
    x = backend_fit,
    variable = variable,
    prior_selection = prior_selection,
    likelihood_selection = likelihood_selection
  )
  args <- args[!vapply(args, is.null, logical(1L))]

  raw <- tryCatch(
    do.call(priorsense::powerscale_sensitivity, args),
    error = function(e) {
      .gp3x_stop(
        "Power-scaling sensitivity failed: ",
        conditionMessage(e),
        " Refit with `fit_*_model_backend()` so that all required ",
        "parameters are saved."
      )
    }
  )

  diagnosis <- tryCatch(
    {
      table <- as.data.frame(raw)
      if ("diagnosis" %in% names(table)) unique(table$diagnosis) else character()
    },
    error = function(e) character()
  )

  structure(
    list(
      status = "review",
      raw = raw,
      fit = fit,
      variable = variable,
      prior_selection = prior_selection,
      likelihood_selection = likelihood_selection,
      diagnoses = diagnosis,
      robustness_established = FALSE,
      interpretation = paste(
        "Power-scaling is a local sensitivity diagnostic.",
        "It does not establish universal robustness."
      )
    ),
    class = "gp3bayes_powerscale_sensitivity"
  )
}

#' Create a Power-Scaling Sequence
#'
#' @inheritParams assess_powerscaled_sensitivity
#' @param component Either prior, likelihood, or both, as supported by
#'   priorsense.
#'
#' @return A priorsense powerscaled sequence.
#' @export
powerscale_sequence_for_fit <- function(
  fit,
  variable = NULL,
  prior_selection = NULL,
  likelihood_selection = NULL,
  component = "both"
) {
  .gp3x_require("priorsense", "create a power-scaling sequence")
  backend_fit <- .gp3x_unwrap_fit(fit)
  args <- list(
    x = backend_fit,
    variable = variable,
    prior_selection = prior_selection,
    likelihood_selection = likelihood_selection,
    component = component
  )
  args <- args[!vapply(args, is.null, logical(1L))]
  do.call(priorsense::powerscale_sequence, args)
}

#' @export
print.gp3bayes_powerscale_sensitivity <- function(x, ...) {
  cat("\nPower-scaled sensitivity audit\n")
  cat(" Status: review\n")
  print(x$raw)
  cat("\nRobustness established: FALSE\n")
  cat(x$interpretation, "\n")
  invisible(x)
}

#' @export
plot.gp3bayes_powerscale_sensitivity <- function(
  x,
  type = c("ecdf", "density", "quantities"),
  quantity = c("mean", "sd"),
  ...
) {
  .gp3x_require("priorsense", "plot power-scaled sensitivity")
  type <- match.arg(type)
  backend_fit <- .gp3x_unwrap_fit(x$fit)

  common <- list(
    x = backend_fit,
    variable = x$variable,
    prior_selection = x$prior_selection,
    likelihood_selection = x$likelihood_selection
  )
  common <- common[!vapply(common, is.null, logical(1L))]
  common <- c(common, list(...))

  if (identical(type, "density")) {
    return(do.call(priorsense::powerscale_plot_dens, common))
  }
  if (identical(type, "ecdf")) {
    return(do.call(priorsense::powerscale_plot_ecdf, common))
  }
  common$quantity <- quantity
  do.call(priorsense::powerscale_plot_quantities, common)
}

#' Simulate a Dedicated Binary Pathology Scenario
#'
#' @param scenario Pathological or stress-test scenario.
#' @param seed Non-negative integer seed.
#'
#' @return A `gp3bayes_pathological_simulation`.
#' @export
simulate_binary_pathology <- function(
  scenario = c(
    "null_contrast",
    "weak_information",
    "severe_imbalance",
    "near_separation",
    "omitted_random_slope",
    "sparse_item_structure",
    "all_zero_participants",
    "rank_deficiency",
    "missing_outcomes"
  ),
  seed = 1L
) {
  scenario <- match.arg(scenario)
  seed <- .gp3x_scalar_integer(seed, "seed", 0L)

  args <- list(
    n_participants = 30L,
    trials_per_participant = 12L,
    n_items = 12L,
    condition_effect = 0.8,
    random_slope_sd = 0.3,
    balanced_condition = TRUE,
    condition_probability = 0.5,
    seed = seed
  )

  if (scenario == "null_contrast") {
    args$condition_effect <- 0
  } else if (scenario == "weak_information") {
    args$n_participants <- 8L
    args$trials_per_participant <- 4L
    args$n_items <- 4L
    args$random_slope_sd <- 0
  } else if (scenario == "severe_imbalance") {
    args$balanced_condition <- FALSE
    args$condition_probability <- 0.95
  } else if (scenario == "near_separation") {
    args$intercept <- -4
    args$condition_effect <- 8
    args$random_slope_sd <- 0
  } else if (scenario == "omitted_random_slope") {
    args$random_slope_sd <- 1
  } else if (scenario == "sparse_item_structure") {
    args$n_items <- 2L
  }

  simulation <- do.call(simulate_hierarchical_binary_data, args)
  data <- simulation$data

  if (scenario == "all_zero_participants") {
    ids <- unique(data$participant_id)[1:2]
    data$selected[data$participant_id %in% ids] <- 0L
  } else if (scenario == "rank_deficiency") {
    data$duplicate_trial_covariate <- data$trial_covariate
  } else if (scenario == "missing_outcomes") {
    set.seed(seed + 1L)
    data$selected[sample.int(nrow(data), max(1L, floor(0.1 * nrow(data))))] <- NA
  }

  expected <- switch(
    scenario,
    null_contrast = "pass_or_review",
    weak_information = "review",
    severe_imbalance = "review_or_fail",
    near_separation = "review",
    omitted_random_slope = "review",
    sparse_item_structure = "review",
    all_zero_participants = "review_or_fail",
    rank_deficiency = "fail",
    missing_outcomes = "fail"
  )

  structure(
    list(
      family = "binary",
      scenario = scenario,
      data = data,
      truth = simulation$truth,
      design = simulation$design,
      expected_gate = expected,
      seed = seed,
      source_simulation = simulation,
      interpretation = paste(
        "This scenario is a deliberate stress or failure case.",
        "A passed structural audit would not establish model adequacy."
      )
    ),
    class = "gp3bayes_pathological_simulation"
  )
}

#' Simulate a Dedicated Duration Pathology Scenario
#'
#' @param scenario Pathological or stress-test duration scenario.
#' @inheritParams simulate_binary_pathology
#'
#' @return A `gp3bayes_pathological_simulation`.
#' @export
simulate_duration_pathology <- function(
  scenario = c(
    "null_ratio",
    "high_group_heterogeneity",
    "weak_information",
    "severe_imbalance",
    "heavy_tailed_contamination",
    "mixture",
    "censoring",
    "incorrect_unit",
    "zero_duration",
    "negative_duration"
  ),
  seed = 1L
) {
  scenario <- match.arg(scenario)
  seed <- .gp3x_scalar_integer(seed, "seed", 0L)

  args <- list(
    n_participants = 30L,
    trials_per_participant = 12L,
    n_items = 12L,
    condition_effect = log(1.15),
    participant_sd = 0.35,
    item_sd = 0.20,
    residual_sd = 0.40,
    balanced_condition = TRUE,
    condition_probability = 0.5,
    outcome_unit = "milliseconds",
    seed = seed
  )

  if (scenario == "null_ratio") {
    args$condition_effect <- 0
  } else if (scenario == "high_group_heterogeneity") {
    args$participant_sd <- 1.0
    args$item_sd <- 0.7
  } else if (scenario == "weak_information") {
    args$n_participants <- 8L
    args$trials_per_participant <- 4L
    args$n_items <- 4L
  } else if (scenario == "severe_imbalance") {
    args$balanced_condition <- FALSE
    args$condition_probability <- 0.95
  }

  simulation <- do.call(simulate_hierarchical_duration_data, args)
  data <- simulation$data

  if (scenario == "heavy_tailed_contamination") {
    set.seed(seed + 1L)
    ids <- sample.int(nrow(data), max(2L, floor(0.05 * nrow(data))))
    data$duration[ids] <- data$duration[ids] * exp(stats::rt(length(ids), 2))
  } else if (scenario == "mixture") {
    set.seed(seed + 1L)
    group <- stats::rbinom(nrow(data), 1L, 0.25)
    data$duration <- data$duration * ifelse(group == 1L, 3.5, 1)
    data$mixture_component <- group
  } else if (scenario == "censoring") {
    deadline <- stats::quantile(data$duration, 0.85)
    data$censored <- data$duration >= deadline
    data$duration <- pmin(data$duration, deadline)
  } else if (scenario == "incorrect_unit") {
    data$duration <- data$duration / 1000
    simulation$truth$outcome_unit <- "milliseconds_declared_but_seconds_stored"
  } else if (scenario == "zero_duration") {
    data$duration[[1L]] <- 0
  } else if (scenario == "negative_duration") {
    data$duration[[1L]] <- -abs(data$duration[[1L]])
  }

  expected <- switch(
    scenario,
    null_ratio = "pass_or_review",
    high_group_heterogeneity = "review",
    weak_information = "review",
    severe_imbalance = "review_or_fail",
    heavy_tailed_contamination = "review_or_fail",
    mixture = "fail_adequacy",
    censoring = "fail_contract",
    incorrect_unit = "fail_contract",
    zero_duration = "fail",
    negative_duration = "fail"
  )

  structure(
    list(
      family = "duration",
      scenario = scenario,
      data = data,
      truth = simulation$truth,
      design = simulation$design,
      expected_gate = expected,
      seed = seed,
      source_simulation = simulation,
      interpretation = paste(
        "This scenario is a deliberate stress or failure case.",
        "Extreme values are not automatically deleted."
      )
    ),
    class = "gp3bayes_pathological_simulation"
  )
}

#' Evaluate a Pathological Simulation Against the Contract Gate
#'
#' @param x A `gp3bayes_pathological_simulation`.
#'
#' @return A `gp3bayes_pathology_evaluation`.
#' @export
evaluate_pathological_simulation <- function(x) {
  if (!inherits(x, "gp3bayes_pathological_simulation")) {
    .gp3x_stop("`x` must be a pathological simulation.")
  }

  semantic_failure <- FALSE
  semantic_reason <- NA_character_

  if (x$family == "duration" && x$scenario == "censoring") {
    semantic_failure <- TRUE
    semantic_reason <- "Censored observations violate the uncensored contract."
  }
  if (x$family == "duration" && x$scenario == "incorrect_unit") {
    semantic_failure <- TRUE
    semantic_reason <- "The stored values and declared measurement unit disagree."
  }

  prepared <- NULL
  error_message <- NULL

  if (!semantic_failure) {
    attempt <- tryCatch(
      {
        predictors <- c("participant_covariate", "trial_covariate")
        if (x$family == "binary" && x$scenario == "rank_deficiency") {
          predictors <- c(predictors, "duplicate_trial_covariate")
        }

        contract <- create_model_contract(
          family = x$family,
          outcome_col = if (x$family == "binary") "selected" else "duration",
          participant_col = "participant_id",
          item_col = "item_id",
          trial_col = "trial_id",
          condition_col = "condition",
          predictors = predictors,
          interaction = c("condition", "participant_covariate"),
          random_slope = !identical(x$scenario, "omitted_random_slope"),
          outcome_unit = if (x$family == "duration") "milliseconds" else NULL
        )

        if (x$family == "binary") {
          prepare_hierarchical_binary_data(
            data = x$data,
            contract = contract,
            condition_levels = c("control", "treatment"),
            missing = "error"
          )
        } else {
          prepare_hierarchical_duration_data(
            data = x$data,
            contract = contract,
            condition_levels = c("control", "treatment"),
            missing = "error"
          )
        }
      },
      error = function(e) e
    )

    if (inherits(attempt, "error")) {
      error_message <- conditionMessage(attempt)
    } else {
      prepared <- attempt
    }
  } else {
    error_message <- semantic_reason
  }

  actual_status <- if (!is.null(error_message)) "fail" else "pass"

  structure(
    list(
      family = x$family,
      scenario = x$scenario,
      expected_gate = x$expected_gate,
      actual_structural_status = actual_status,
      error = error_message,
      prepared = prepared,
      semantic_failure = semantic_failure,
      interpretation = paste(
        "Structural status is not a posterior adequacy decision.",
        "Review the expected failure mechanism and diagnostic context."
      )
    ),
    class = "gp3bayes_pathology_evaluation"
  )
}

#' @export
print.gp3bayes_pathological_simulation <- function(x, ...) {
  cat("\nPathological simulation\n")
  cat(" Family: ", x$family, "\n", sep = "")
  cat(" Scenario: ", x$scenario, "\n", sep = "")
  cat(" Rows: ", nrow(x$data), "\n", sep = "")
  cat(" Expected gate: ", x$expected_gate, "\n", sep = "")
  cat(x$interpretation, "\n")
  invisible(x)
}

#' @export
plot.gp3bayes_pathological_simulation <- function(x, ...) {
  if (x$family == "binary") {
    rates <- tapply(x$data$selected, x$data$participant_id, mean, na.rm = TRUE)
    graphics::hist(
      rates,
      xlab = "Participant event rate",
      main = paste("Binary pathology:", x$scenario),
      ...
    )
  } else {
    graphics::hist(
      log(pmax(x$data$duration, .Machine$double.eps)),
      xlab = "Log duration",
      main = paste("Duration pathology:", x$scenario),
      ...
    )
  }
  invisible(x)
}

#' @export
print.gp3bayes_pathology_evaluation <- function(x, ...) {
  cat("\nPathology evaluation\n")
  cat(" Family: ", x$family, "\n", sep = "")
  cat(" Scenario: ", x$scenario, "\n", sep = "")
  cat(" Expected gate: ", x$expected_gate, "\n", sep = "")
  cat(" Structural status: ", x$actual_structural_status, "\n", sep = "")
  if (!is.null(x$error)) {
    cat(" Reason: ", x$error, "\n", sep = "")
  }
  cat(x$interpretation, "\n")
  invisible(x)
}

#' Create a brms-Based Simulation-Based Calibration Plan
#'
#' Constructs a complete SBC generator/backend pair using the restricted
#' gp3bayes brms translation. Because the generator and backend share brms
#' implementation code, this plan is mainly a computational-calibration check;
#' custom independent generators remain preferable for detecting shared
#' implementation errors.
#'
#' @param specification An approved binary or duration specification.
#' @param n_sims Number of simulated datasets.
#' @param backend Either rstan or cmdstanr.
#' @param chains Number of chains used per SBC fit.
#' @param iter Total iterations per SBC fit.
#' @param warmup Warmup iterations.
#' @param thin Thinning interval.
#' @param seed Seed used when datasets are generated.
#' @param generator_iter Total prior-only generator iterations.
#' @param generator_warmup Prior-only generator warmup.
#'
#' @return A `gp3bayes_sbc_plan`.
#' @export
create_brms_sbc_plan <- function(
  specification,
  n_sims = 20L,
  backend = c("rstan", "cmdstanr"),
  chains = 2L,
  iter = 1000L,
  warmup = 500L,
  thin = 1L,
  seed = 1L,
  generator_iter = 3000L,
  generator_warmup = 2000L
) {
  .gp3x_require("SBC", "create a simulation-based calibration plan")
  .gp3x_require("brms", "create a brms SBC generator")
  backend <- match.arg(backend)

  if (backend == "rstan") {
    .gp3x_require("rstan", "use the rstan SBC backend")
  } else {
    check_cmdstan_backend(strict = TRUE)
  }

  n_sims <- .gp3x_scalar_integer(n_sims, "n_sims", 1L)
  chains <- .gp3x_scalar_integer(chains, "chains", 1L)
  iter <- .gp3x_scalar_integer(iter, "iter", 100L)
  warmup <- .gp3x_scalar_integer(warmup, "warmup", 0L)
  thin <- .gp3x_scalar_integer(thin, "thin", 1L)
  seed <- .gp3x_scalar_integer(seed, "seed", 0L)
  generator_iter <- .gp3x_scalar_integer(
    generator_iter, "generator_iter", 100L
  )
  generator_warmup <- .gp3x_scalar_integer(
    generator_warmup, "generator_warmup", 0L
  )

  if (warmup >= iter || generator_warmup >= generator_iter) {
    .gp3x_stop("Warmup must be smaller than total iterations.")
  }

  translation <- .gp3x_translate_for_backend(specification)

  generator <- SBC::SBC_generator_brms(
    formula = translation$formula,
    data = specification$prepared$data,
    family = translation$family_object,
    prior = translation$priors,
    backend = backend,
    algorithm = "sampling",
    chains = 1L,
    iter = generator_iter,
    warmup = generator_warmup,
    thin = max(
      1L,
      floor((generator_iter - generator_warmup) / n_sims)
    ),
    generate_lp = TRUE,

    # SBC 0.5.0.9000 uses brms::log_lik() in its chunked branch but an
    # unqualified log_lik() call in its serial branch. A chunk size of one
    # keeps likelihood generation namespace-safe for n_sims >= 2.
    generate_lp_chunksize = 1L,

    refresh = 0
  )

  inference_backend <- SBC::SBC_backend_brms_from_generator(
    generator,
    chains = chains,
    iter = iter,
    warmup = warmup,
    thin = thin,
    algorithm = "sampling",
    refresh = 0
  )

  structure(
    list(
      plan_version = "0.2",
      family = specification$family,
      specification = specification,
      translation = translation,
      generator = generator,
      inference_backend = inference_backend,
      n_sims = n_sims,
      backend = backend,
      seed = seed,
      shared_implementation = TRUE,
      interpretation = paste(
        "The brms generator and brms backend share implementation code.",
        "Use an independently coded generator for stronger implementation validation."
      )
    ),
    class = "gp3bayes_sbc_plan"
  )
}

#' Create an Expert Custom SBC Plan
#'
#' Wraps an independently coded generator function and a user-supplied SBC
#' backend. The generator must return `variables` and `generated` elements as
#' required by SBC.
#'
#' @param generator_function Function producing one SBC dataset.
#' @param backend A valid SBC backend object.
#' @param n_sims Number of datasets.
#' @param generator_args Named list passed to the generator constructor.
#' @param seed Seed used for dataset generation.
#'
#' @return A `gp3bayes_sbc_plan`.
#' @export
create_custom_sbc_plan <- function(
  generator_function,
  backend,
  n_sims = 20L,
  generator_args = list(),
  seed = 1L
) {
  .gp3x_require("SBC", "create a custom simulation-based calibration plan")
  if (!is.function(generator_function)) {
    .gp3x_stop("`generator_function` must be a function.")
  }
  if (!is.list(generator_args) || is.null(names(generator_args)) &&
      length(generator_args) > 0L) {
    .gp3x_stop("`generator_args` must be a named list.")
  }

  n_sims <- .gp3x_scalar_integer(n_sims, "n_sims", 2L)
  seed <- .gp3x_scalar_integer(seed, "seed", 0L)

  generator <- do.call(
    SBC::SBC_generator_function,
    c(list(f = generator_function), generator_args)
  )

  structure(
    list(
      plan_version = "0.2",
      family = "custom",
      specification = NULL,
      translation = NULL,
      generator = generator,
      inference_backend = backend,
      n_sims = n_sims,
      backend = class(backend)[[1L]],
      seed = seed,
      shared_implementation = FALSE,
      interpretation = paste(
        "The generator is independently supplied.",
        "Calibration still depends on adequate simulation count and diagnostics."
      )
    ),
    class = "gp3bayes_sbc_plan"
  )
}

#' Run a Simulation-Based Calibration Plan
#'
#' @param plan A `gp3bayes_sbc_plan`.
#' @param cores_per_fit Cores used by each fit.
#' @param keep_fits Whether to retain fitted objects.
#' @param thin_ranks Optional rank thinning.
#' @param cache_mode SBC cache mode.
#' @param cache_location Optional cache location.
#'
#' @return A `gp3bayes_sbc_result`.
#' @export
run_sbc_plan <- function(
  plan,
  cores_per_fit = 1L,
  keep_fits = FALSE,
  thin_ranks = NULL,
  cache_mode = "none",
  cache_location = NULL
) {
  .gp3x_require("SBC", "run simulation-based calibration")
  if (!inherits(plan, "gp3bayes_sbc_plan")) {
    .gp3x_stop("`plan` must be a gp3bayes SBC plan.")
  }

  set.seed(plan$seed)
  datasets <- SBC::generate_datasets(
    plan$generator,
    n_sims = plan$n_sims
  )

  args <- list(
    datasets = datasets,
    backend = plan$inference_backend,
    cores_per_fit = cores_per_fit,
    keep_fits = keep_fits,
    cache_mode = cache_mode,
    cache_location = cache_location
  )
  if (!is.null(thin_ranks)) {
    args$thin_ranks <- thin_ranks
  }
  args <- args[!vapply(args, is.null, logical(1L))]

  raw <- do.call(SBC::compute_SBC, args)

  diagnostics_ok <- tryCatch(
    {
      diagnostic_columns <- grep(
        "diagnostic|error|warning",
        names(raw$stats),
        ignore.case = TRUE,
        value = TRUE
      )
      if (length(diagnostic_columns) == 0L) {
        NA
      } else {
        TRUE
      }
    },
    error = function(e) NA
  )

  status <- if (plan$n_sims < 20L) "review" else "review"

  structure(
    list(
      status = status,
      plan = plan,
      datasets = datasets,
      raw = raw,
      diagnostics_inspected = diagnostics_ok,
      calibration_established = FALSE,
      interpretation = paste(
        "SBC results require graphical and diagnostic review.",
        "Absence of detected failures does not prove implementation correctness."
      )
    ),
    class = "gp3bayes_sbc_result"
  )
}

#' Summarise an SBC Result
#'
#' @param x A `gp3bayes_sbc_result`.
#'
#' @return A conservative summary list.
#' @export
summarise_sbc_result <- function(x) {
  if (!inherits(x, "gp3bayes_sbc_result")) {
    .gp3x_stop("`x` must be a gp3bayes SBC result.")
  }
  list(
    status = x$status,
    family = x$plan$family,
    backend = x$plan$backend,
    simulations = x$plan$n_sims,
    shared_implementation = x$plan$shared_implementation,
    calibration_established = FALSE,
    stats = x$raw$stats,
    interpretation = x$interpretation
  )
}

#' @export
print.gp3bayes_sbc_plan <- function(x, ...) {
  cat("\nSimulation-based calibration plan\n")
  cat(" Family: ", x$family, "\n", sep = "")
  cat(" Backend: ", x$backend, "\n", sep = "")
  cat(" Simulations: ", x$n_sims, "\n", sep = "")
  cat(" Shared generator/backend implementation: ",
      x$shared_implementation, "\n", sep = "")
  cat(x$interpretation, "\n")
  invisible(x)
}

#' @export
print.gp3bayes_sbc_result <- function(x, ...) {
  cat("\nSimulation-based calibration result\n")
  cat(" Status: ", x$status, "\n", sep = "")
  cat(" Simulations: ", x$plan$n_sims, "\n", sep = "")
  cat(" Calibration established: FALSE\n")
  print(x$raw)
  cat(x$interpretation, "\n")
  invisible(x)
}

#' @export
plot.gp3bayes_sbc_result <- function(
  x,
  type = c("rank", "ecdf", "coverage", "simulated_vs_estimated"),
  ...
) {
  .gp3x_require("SBC", "plot simulation-based calibration results")
  type <- match.arg(type)
  if (type == "rank") {
    return(SBC::plot_rank_hist(x$raw, ...))
  }
  if (type == "ecdf") {
    return(SBC::plot_ecdf_diff(x$raw, ...))
  }
  if (type == "coverage") {
    return(SBC::plot_coverage(x$raw, ...))
  }
  SBC::plot_sim_estimated(x$raw, ...)
}
